import { useIsAuthenticated } from 'react-auth-kit'
import { Helmet } from 'react-helmet-async'

import {
  Box,
  Button,
  CircularProgress,
  Container,
  Grid,
  Stack,
  Typography,
  useMediaQuery,
  useTheme
} from '@mui/material'

import { COMMON_MESSAGE } from 'src/data/messages'

import { getActivePartnerCouponItems } from 'src/utils/partnerBenefits'

import PageTitleWrapper from 'src/components/PageTitleWrapper'
import PartnerCouponCard from 'src/components/PartnerCouponCard'

import { usePartnerBenefits } from 'src/hooks/usePartnerBenefits'

const BenefitCouponListPage: React.FC = () => {
  const theme = useTheme()
  const isMobile = useMediaQuery(theme.breakpoints.down('sm'))
  const isAuthenticated = useIsAuthenticated()
  const { stores, coupons, isError, isLoading, refreshPartnerBenefits } = usePartnerBenefits()
  const activePartnerCouponItems = getActivePartnerCouponItems({ stores, coupons })
  const isLoggedIn = isAuthenticated()

  const handleRetryButtonClick: React.MouseEventHandler<HTMLButtonElement> = () => {
    refreshPartnerBenefits()
  }

  return (
    <>
      <Helmet>
        <title>쿠폰 혜택 - KLUB</title>
      </Helmet>
      <PageTitleWrapper>
        <Grid container alignItems="center" justifyContent="space-between" spacing={2}>
          <Grid item xs={12} md>
            <Stack direction="row" alignItems="baseline">
              <Typography variant={isMobile ? 'h4' : 'h3'} component="h3" gutterBottom sx={{ marginTop: 1 }}>
                쿠폰 혜택
              </Typography>
            </Stack>
            <Typography variant={isMobile ? 'body2' : 'subtitle2'}>
              동아리에 소속된 회원만 인증 후 사용할 수 있는 제휴 쿠폰 혜택을 확인해보세요
            </Typography>
          </Grid>
        </Grid>
      </PageTitleWrapper>
      <Container maxWidth="xl" sx={{ py: 3 }}>
        {!isLoggedIn ? (
          <Box
            sx={{
              minHeight: 280,
              display: 'flex',
              flexDirection: 'column',
              alignItems: 'center',
              justifyContent: 'center',
              gap: 2,
              bgcolor: theme.palette.background.paper,
              borderRadius: theme.general.borderRadius,
              border: `1px solid ${theme.palette.divider}`
            }}
          >
            <Typography color="text.secondary">로그인 후 제휴 쿠폰 혜택을 확인할 수 있습니다.</Typography>
            <Button variant="contained" href="/auth/login">
              로그인하기
            </Button>
          </Box>
        ) : isLoading ? (
          <Box
            sx={{
              minHeight: 280,
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              bgcolor: theme.palette.background.paper,
              borderRadius: theme.general.borderRadius,
              border: `1px solid ${theme.palette.divider}`
            }}
          >
            <CircularProgress />
          </Box>
        ) : isError ? (
          <Box
            sx={{
              minHeight: 280,
              display: 'flex',
              flexDirection: 'column',
              alignItems: 'center',
              justifyContent: 'center',
              gap: 2,
              bgcolor: theme.palette.background.paper,
              borderRadius: theme.general.borderRadius,
              border: `1px solid ${theme.palette.divider}`
            }}
          >
            <Typography color="text.secondary">{COMMON_MESSAGE.LOAD_FAIL}</Typography>
            <Button variant="contained" onClick={handleRetryButtonClick}>
              다시 시도
            </Button>
          </Box>
        ) : activePartnerCouponItems.length > 0 ? (
          <Box
            data-testid="benefit-coupon-grid"
            sx={{
              display: 'grid',
              gridTemplateColumns: {
                xs: '1fr',
                md: 'repeat(2, minmax(0, 1fr))',
                lg: 'repeat(3, minmax(0, 1fr))'
              },
              gap: 3
            }}
          >
            {activePartnerCouponItems.map(partnerCouponItem => (
              <PartnerCouponCard key={partnerCouponItem.coupon.id} partnerCouponItem={partnerCouponItem} />
            ))}
          </Box>
        ) : (
          <Box
            sx={{
              minHeight: 280,
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              bgcolor: theme.palette.background.paper,
              borderRadius: theme.general.borderRadius,
              border: `1px solid ${theme.palette.divider}`
            }}
          >
            <Typography color="text.secondary">현재 사용 가능한 쿠폰 혜택이 없습니다.</Typography>
          </Box>
        )}
      </Container>
    </>
  )
}

export default BenefitCouponListPage
