import { useState } from 'react'
import { useNavigate } from 'react-router'

import ArrowForwardIcon from '@mui/icons-material/ArrowForward'
import LockRoundedIcon from '@mui/icons-material/LockRounded'
import PlaceIcon from '@mui/icons-material/Place'
import RepeatIcon from '@mui/icons-material/Repeat'
import RestaurantIcon from '@mui/icons-material/Restaurant'
import StorefrontIcon from '@mui/icons-material/Storefront'
import { Box, Button, Card, CardMedia, Chip, Stack, Typography, alpha, useTheme } from '@mui/material'

import { PARTNER_COUPON_UNLOCK_TYPE_LABELS, PARTNER_COUPON_USAGE_TYPE_LABELS } from 'src/data/partnerBenefits'

import { getIsPartnerCouponLocked } from 'src/utils/partnerBenefits'

import type { PartnerCouponWithStore } from 'src/models/partnerBenefit'

interface PartnerCouponCardProps {
  partnerCouponItem: PartnerCouponWithStore
}

const PartnerCouponCard: React.FC<PartnerCouponCardProps> = ({ partnerCouponItem }) => {
  const theme = useTheme()
  const navigate = useNavigate()
  const { coupon, store } = partnerCouponItem
  const isLocked = getIsPartnerCouponLocked(coupon)
  const [isImageError, setIsImageError] = useState(false)

  const handleDetailButtonClick: React.MouseEventHandler<HTMLButtonElement> = () => {
    navigate(`/benefit-coupons/${coupon.id}`)
  }

  const handleCouponImageError: React.ReactEventHandler<HTMLImageElement> = () => {
    setIsImageError(true)
  }

  return (
    <Card
      data-testid="partner-coupon-card"
      sx={{
        height: '100%',
        display: 'flex',
        flexDirection: 'column',
        overflow: 'hidden',
        border: `1px solid ${theme.palette.divider}`,
        boxShadow: theme.header.boxShadow
      }}
    >
      <Box sx={{ position: 'relative', aspectRatio: '16 / 9', bgcolor: theme.colors.alpha.black[5] }}>
        {store.imageUrl && !isImageError ? (
          <CardMedia
            component="img"
            image={store.imageUrl}
            alt={`${store.name} 이미지`}
            onError={handleCouponImageError}
            sx={{ width: '100%', height: '100%', objectFit: 'cover' }}
          />
        ) : (
          <Box
            sx={{
              width: '100%',
              height: '100%',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              color: theme.colors.alpha.black[30]
            }}
          >
            <StorefrontIcon sx={{ fontSize: 64 }} />
          </Box>
        )}
        <Chip
          label="회원 전용"
          size="small"
          sx={{
            position: 'absolute',
            top: theme.spacing(1.5),
            left: theme.spacing(1.5),
            bgcolor: theme.palette.background.paper,
            color: theme.palette.text.primary,
            fontWeight: 700
          }}
        />
        {isLocked && (
          <Box
            sx={{
              position: 'absolute',
              inset: 0,
              bgcolor: alpha(theme.palette.common.black, 0.62),
              color: theme.palette.common.white,
              display: 'flex',
              flexDirection: 'column',
              alignItems: 'center',
              justifyContent: 'center',
              gap: 0.5,
              textAlign: 'center',
              px: 2
            }}
          >
            <LockRoundedIcon sx={{ fontSize: 42 }} />
            <Typography sx={{ fontWeight: 700 }}>잠금된 혜택</Typography>
            <Typography variant="body2">
              {PARTNER_COUPON_UNLOCK_TYPE_LABELS[coupon.lockReason ?? coupon.unlockType]}
            </Typography>
          </Box>
        )}
      </Box>
      <Stack spacing={1.5} sx={{ p: 2.5, flex: 1 }}>
        <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 1 }}>
          <Chip label={store.category || '제휴'} size="small" variant="outlined" />
          <Chip
            icon={<RepeatIcon />}
            label={PARTNER_COUPON_USAGE_TYPE_LABELS[coupon.usageType]}
            size="small"
            variant="outlined"
          />
          {isLocked && (
            <Chip
              icon={<LockRoundedIcon />}
              label={PARTNER_COUPON_UNLOCK_TYPE_LABELS[coupon.lockReason ?? coupon.unlockType]}
              color="warning"
              size="small"
              variant="outlined"
            />
          )}
        </Box>
        <Box>
          <Typography variant="h4" sx={{ mb: 1 }}>
            {store.name}
          </Typography>
          <Stack direction="row" spacing={0.75} alignItems="center" sx={{ color: theme.palette.text.secondary }}>
            <PlaceIcon fontSize="small" />
            <Typography variant="body2">{store.locationLabel || store.address || '지도 링크에서 위치 확인'}</Typography>
          </Stack>
        </Box>
        <Box
          sx={{
            border: `1px solid ${isLocked ? theme.colors.warning.light : theme.colors.error.light}`,
            bgcolor: isLocked ? theme.colors.warning.lighter : theme.colors.error.lighter,
            borderRadius: theme.general.borderRadius,
            px: 2,
            py: 1.5
          }}
        >
          <Typography
            sx={{
              color: isLocked ? theme.colors.warning.dark : theme.colors.error.dark,
              fontWeight: 700,
              fontSize: 17,
              lineHeight: 1.45,
              wordBreak: 'keep-all'
            }}
          >
            {coupon.benefitContent}
          </Typography>
        </Box>
        <Box sx={{ flex: 1 }}>
          <Typography variant="caption" color="text.secondary">
            사용 조건
          </Typography>
          <Typography sx={{ mt: 0.5, fontWeight: 700, wordBreak: 'keep-all' }}>{coupon.audience}</Typography>
        </Box>
        {coupon.recommendedMenu && (
          <Stack direction="row" spacing={0.75} alignItems="center" sx={{ color: theme.palette.text.secondary }}>
            <RestaurantIcon fontSize="small" />
            <Typography variant="body2">{coupon.recommendedMenu}</Typography>
          </Stack>
        )}
        <Button variant="contained" endIcon={<ArrowForwardIcon />} onClick={handleDetailButtonClick} fullWidth>
          상세 보기
        </Button>
      </Stack>
    </Card>
  )
}

export default PartnerCouponCard
